"""
Predictor Module for Crop Disease Detection.
Handles end-to-end inference execution, softmax probability extraction,
top-K ranking, and disease knowledge base integration.
"""

import logging
from typing import Dict, Any, Union, BinaryIO, Optional
import numpy as np
from PIL import Image

from .preprocessing import preprocess_image, validate_image_file
from .model_loader import get_model, get_class_names
from disease_info import get_disease_info

logger = logging.getLogger(__name__)

DISCLAIMER_TEXT = (
    "Disclaimer: This classification is generated by a Convolutional Neural Network (CNN) trained "
    "primarily on the PlantVillage dataset under controlled lighting conditions. "
    "Confidence scores represent model prediction probabilities and should not be considered "
    "an absolute agricultural diagnosis. Always consult a certified local agronomist or plant pathologist "
    "before making financial or chemical management decisions."
)


def predict_crop_disease(
    image_input: Union[BinaryIO, bytes, str, Image.Image],
    top_k: int = 3,
    model: Optional[Any] = None,
    class_names: Optional[list] = None
) -> Dict[str, Any]:
    """
    Executes actual CNN inference on an input image:
    1. Loads model and class mappings if not explicitly provided.
    2. Validates and preprocesses image into normalized tensor.
    3. Runs model forward pass.
    4. Computes softmax probabilities.
    5. Retrieves top-1 prediction and top-K alternatives.
    6. Attaches detailed agronomic information from the knowledge base.
    """
    if model is None:
        model = get_model()

    if class_names is None:
        class_names = get_class_names()

    if model is None:
        raise RuntimeError("CNN model is not loaded. Train or provide a valid model artifact first.")

    if not class_names:
        raise RuntimeError("Class names mapping is missing or empty. Cannot map predictions to labels.")

    # 1. Preprocess input image
    input_tensor = preprocess_image(image_input)

    # 2. Forward pass inference
    raw_predictions = model.predict(input_tensor, verbose=0)
    probabilities = np.squeeze(raw_predictions)

    # In case model outputs raw logits without Softmax activation
    if np.any(probabilities < 0) or not np.isclose(np.sum(probabilities), 1.0, atol=1e-2):
        exp_preds = np.exp(probabilities - np.max(probabilities))
        probabilities = exp_preds / np.sum(exp_preds)

    num_classes = len(class_names)
    if len(probabilities) != num_classes:
        raise ValueError(
            f"Model output dimension ({len(probabilities)}) does not match class list length ({num_classes})."
        )

    # 3. Rank top classes
    sorted_indices = np.argsort(probabilities)[::-1]
    top_index = int(sorted_indices[0])
    top_class = class_names[top_index]
    top_confidence = float(probabilities[top_index])

    # 4. Compile top-K list
    top_predictions = []
    effective_k = min(top_k, num_classes)
    for i in range(effective_k):
        idx = int(sorted_indices[i])
        cls_name = class_names[idx]
        conf = float(probabilities[idx])
        top_predictions.append({
            "rank": i + 1,
            "class_name": cls_name,
            "display_name": cls_name.replace("___", " - ").replace("_", " "),
            "confidence_ratio": round(conf, 4),
            "confidence_percent": round(conf * 100.0, 2)
        })

    # 5. Retrieve agronomic profile from knowledge base
    disease_info = get_disease_info(top_class)

    return {
        "success": True,
        "predicted_class": top_class,
        "display_name": top_class.replace("___", " - ").replace("_", " "),
        "crop": disease_info.get("crop", "Unknown"),
        "disease": disease_info.get("disease", "Unknown"),
        "is_healthy": disease_info.get("is_healthy", False),
        "confidence": round(top_confidence, 4),
        "confidence_percentage": round(top_confidence * 100.0, 2),
        "top_predictions": top_predictions,
        "disease_information": disease_info,
        "disclaimer": DISCLAIMER_TEXT
    }
